+\frac12\sum_{i,j=1}^{2}M_{ij,\alpha\beta}\,F_{j\beta},\\[4pt]
V_{Q\alpha}&=\dot\gamma\,Q_{y}\,\delta_{\alpha x}
+\sum_{j=1}^{2}\bigl(M_{2j,\alpha\beta}-M_{1j,\alpha\beta}\bigr)\,F_{j\beta},
\end{aligned}
}
\]

